// ppmd is written by Dmitry Shkarin.
// mod_ppmd is adapted from ppmd by Eugene Shelwien.
// This file is adapted from mod_ppmd_v2: http://encode.su/threads/2515-mod_ppmd
//
// cmix-lex note: disk-backed mmap mode is output-neutral but needs careful RSS
// control for Hutter's memory limit.  PPMD stores raw pointers inside
// HeapStart, so the mapped address must remain stable.  The upstream fx2-cmix
// style munmap()+mmap() cycle achieved eviction, but it destroyed the VMA,
// relied on the kernel returning the same address, and left Linux free to do
// useless readahead on a random-access PPM tree.
//
// cmix-lex keeps the mapping stable and controls residency with a deterministic
// MADV_DONTNEED cadence.  This drops the file-backed PPM pages from VmRSS while
// preserving pointer values and model bytes.  MADV_RANDOM is applied because
// the PPM heap is pointer-chased, not sequential, and ppm.temp is opened with
// O_NOATIME to avoid metadata writes from repeated page-fault reads.  This was
// a small OS-aware change, but it removed most wasted read traffic and made the
// completed WSL2/SATA run practical without changing compression decisions.

#include "ppmd.h"
#include <cstring>
#include <sys/mman.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <fcntl.h>
#include <cstdio>

namespace PPMD {

template <class T> T Min( T x, T y ) { return (x<y) ? x : y; }
template <class T> T Max( T x, T y ) { return (x>y) ? x : y; }

#pragma pack(1)

typedef unsigned short word;
typedef unsigned int uint;
typedef unsigned char byte;
typedef unsigned long long qword;

// If mmap_to_disk is set to false (recommended setting), PPM will only use RAM
// for memory.
// If mmap_to_disk is set to true, PPM memory will be saved to disk using mmap.
// This will reduce RAM usage, but will be slower as well. *Warning*: this will
// write a *lot* of data to disk, so can reduce the lifespan of SSDs. Not
// recommended for normal usage.
// lext_big knob (2026-09-09): -DCMIX_MMAP_TO_DISK=1 keeps the PPM heap in a MAP_SHARED file (the authors' setting for the
// Hutter 10 GB RAM rule); unset/0 = plain RAM (what every Modal benchmark build used, formerly via a sed on this line).
#ifndef CMIX_MMAP_TO_DISK
#define CMIX_MMAP_TO_DISK 0
#endif
bool mmap_to_disk = (CMIX_MMAP_TO_DISK != 0);
qword mmap_size;
static constexpr char mmap_path[] = "ppm.temp";

// Disk-backed PPM keeps the 14GB heap outside anonymous RAM, but pages still
// count in RSS while resident.  Periodic MADV_DONTNEED calls drop that
// residency without changing the file-backed model state.
#ifndef CMIX_PPMD_REMAP_INTERVAL
#define CMIX_PPMD_REMAP_INTERVAL 5000ULL
#endif
static constexpr unsigned long long kMmapRemapIntervalBytes =
    CMIX_PPMD_REMAP_INTERVAL;

const int ORealMAX=256;

// lext_big memory knobs (all compile-time; defaults reproduce cmix-lex exactly).
// PPMD_TEXT_DIV: the sub-allocator splits its heap into a raw-text area
// (1/PPMD_TEXT_DIV, must hold the whole input stream) and a units area.
// Ptr2Indx/Indx2Ptr compress pointers into 32 bits as text_bytes + units/12,
// so the heap size S is bounded by S/D + (S-S/D)/12 < 2^32: D=8 allows
// S < ~20700 MB, D=32 allows S < ~36700 MB.
#ifndef PPMD_TEXT_DIV
#define PPMD_TEXT_DIV 8
#endif
static_assert(PPMD_TEXT_DIV >= 2, "PPMD_TEXT_DIV");

static signed char EscCoef[12] = { 16, -10, 1, 51, 14, 89, 23, 35, 64, 26, -42, 43 };

static const byte ExpEscape[16]={ 51,43,18,12,11,9,8,7,6,5,4,3,3,2,2,2 };

struct ppmd_Model {

  typedef unsigned short word;
  typedef unsigned int uint;
  typedef unsigned char byte;
  typedef unsigned long long qword;

  enum{ SCALE=1<<15 };

  enum{
    UNIT_SIZE=12,
    N1=4, N2=4, N3=4, N4=(128+3-1*N1-2*N2-3*N3)/4,
    N_INDEXES=N1+N2+N3+N4
  };

  byte* HeapStart;
  // lext_big fix (2026-09-09): the 32-bit compressed pointers used to be defined relative to UnitsStart, but
  // AllocUnitsRare() MOVES UnitsStart down when the units area is exhausted ("UnitsStart -= i", carving units out
  // of the text area) and Expand/PrepareTextArea() move it up during a cut-off -- which silently remapped every
  // stored index (iSuccessor / iSuffix / iStats / free-list links) and corrupted the model the first time the heap
  // got full (segfault at ~9 % of enwik9 with a 1300 MB heap; never triggered with cmix-lex's 14 GB heap, whose
  // UnitsStart never moves on enwik9). The mapping is now anchored to UnitsBase = the boundary set by
  // InitSubAllocator(). It is a bijection on every address the allocator hands out (text bytes and units carved
  // below UnitsBase are addressed linearly; units at or above it are 12-byte aligned relative to it) and it is
  // monotonic, so the index comparisons in ReduceOrder/cutOff keep their meaning. Output is unchanged for runs in
  // which UnitsStart never moves.
  byte* UnitsBase;

  uint Ptr2Indx( void* p ) {
    qword addr = ((byte*)p)-HeapStart;
    uint lim = (UnitsBase-HeapStart);
    uint indx = (addr>=lim) ? (addr-lim)/UNIT_SIZE+lim : addr;
    return indx;
  }

  void* Indx2Ptr( uint indx ) {
    uint lim = (UnitsBase-HeapStart);
    qword addr = (indx>=lim) ? qword(indx-lim)*UNIT_SIZE+lim : indx;
    return HeapStart + addr;
  }

struct _MEM_BLK {
  uint Stamp;
  uint NextIndx;
  uint NU;
};

struct BLK_NODE {
  uint Stamp;
  uint NextIndx;
  int avail() const { return (NextIndx!=0); }
};

BLK_NODE* getNext( BLK_NODE* This ) {
  return (BLK_NODE*)Indx2Ptr(This->NextIndx);
}

void setNext( BLK_NODE* This, BLK_NODE* p ) {
  This->NextIndx = Ptr2Indx(p);
}

void link( BLK_NODE* This, BLK_NODE* p ) {
  p->NextIndx = This->NextIndx;
  setNext( This, p );
}

void unlink( BLK_NODE* This ) {
  This->NextIndx = getNext(This)->NextIndx;
}

void* remove( BLK_NODE* This ) {
  BLK_NODE* p = getNext(This);
  unlink(This);
  This->Stamp--;
  return p;
}

void insert( BLK_NODE* This, void* pv, int NU ) {
  BLK_NODE* p = (BLK_NODE*)pv;
  link(This,p);
  p->Stamp = ~uint(0);
  ((_MEM_BLK&)*p).NU = NU;
  This->Stamp++;
}

struct MEM_BLK : public BLK_NODE {
  uint NU;
};

typedef BLK_NODE* pBLK_NODE;

typedef MEM_BLK* pMEM_BLK;

BLK_NODE BList[N_INDEXES+1];

  uint GlueCount;
  uint GlueCount1;
  qword SubAllocatorSize;
  byte* pText;
  byte* UnitsStart;
  byte* LoUnit;
  byte* HiUnit;
  byte* AuxUnit;

uint U2B( uint NU ) {
  return 8*NU+4*NU;
}

int StartSubAllocator( qword SASize ) {
  qword t = SASize << 20U;

  if (mmap_to_disk) {
    mmap_size = t;
    int fd = open(mmap_path, O_RDWR | O_CREAT | O_TRUNC | O_NOATIME,
        (mode_t)0664);
    if(fd < 0){
      exit(EXIT_FAILURE);
    }

    if (ftruncate(fd, t) == -1) {
      exit(EXIT_FAILURE);
    }
    HeapStart = (byte*) mmap(NULL, t, PROT_READ|PROT_WRITE, MAP_SHARED, fd, 0);
    if(HeapStart == MAP_FAILED){
      exit(EXIT_FAILURE);
    }
    if (madvise(HeapStart, t, MADV_RANDOM) != 0) {
      exit(EXIT_FAILURE);
    }
    close(fd);
  } else {
    HeapStart = new byte[t];
  }

  if( HeapStart==NULL ) return 0;
  SubAllocatorSize = t;
  return 1;
}

void InitSubAllocator() {
  memset( BList, 0, sizeof(BList) );
  HiUnit = (pText=HeapStart) + SubAllocatorSize;
  qword Diff = SubAllocatorSize/PPMD_TEXT_DIV/UNIT_SIZE*(PPMD_TEXT_DIV-1) *UNIT_SIZE ;
  // The 32-bit compressed index must be able to address the top of the heap.
  if( (SubAllocatorSize-Diff) + Diff/UNIT_SIZE + 64 > qword(~uint(0)) ) {
    fprintf(stderr, "ppmd: heap of %llu bytes too large for 32-bit indices "
        "(text/%d split); lower PPMD_MEM_MB or raise PPMD_TEXT_DIV\n",
        (unsigned long long)SubAllocatorSize, PPMD_TEXT_DIV);
    exit(EXIT_FAILURE);
  }
  LoUnit = UnitsStart = UnitsBase = HiUnit-Diff;
  GlueCount=GlueCount1=0;

}

qword GetUsedMemory() {
  int i;
  qword RetVal = SubAllocatorSize - (HiUnit-LoUnit) - (UnitsStart-pText);
  for( i=0; i<N_INDEXES; i++ ) {

    RetVal -= qword(Indx2Units[i]*BList[i].Stamp)*12;
  }
  return RetVal;
}

void StopSubAllocator() {
  if( SubAllocatorSize ) SubAllocatorSize=0, delete[] HeapStart;

}

void GlueFreeBlocks() {
  uint i, k, sz;
  MEM_BLK s0;
  pMEM_BLK p, p0=&s0, p1;

  if( LoUnit!=HiUnit ) LoUnit[0]=0;

  for( p0->NextIndx=0,i=0; i<=N_INDEXES; i++ ) {
     while( BList[i].avail() ) {
       p = (MEM_BLK*)remove(&BList[i]);
       if( p->NU ) {
         while( p1 = p + p->NU, p1->Stamp==~uint(0) ) {
           p->NU += p1->NU;
           p1->NU = 0;
         }
         link(p0,p); p0=p;
       }
     }
  }

  while( s0.avail() ) {
    p = (MEM_BLK*)remove(&s0);
    sz= p->NU;
    if( sz ) {
      for(; sz>128; sz-=128, p+=128 ) insert(&BList[N_INDEXES-1],p,128);
      i = Units2Indx[sz-1];
      if( Indx2Units[i] != sz ) {
        k = sz - Indx2Units[--i];
        insert( &BList[k-1], p+(sz-k) , k );
      }
      insert( &BList[i], p, Indx2Units[i] );
    }
  }

  GlueCount = 1 << (13+GlueCount1++);
}

void SplitBlock( void* pv, uint OldIndx, uint NewIndx ) {
  uint i, k, UDiff=Indx2Units[OldIndx]-Indx2Units[NewIndx];
  byte* p = ((byte*)pv)+U2B(Indx2Units[NewIndx]);
  i = Units2Indx[UDiff-1];
  if( Indx2Units[i]!=UDiff ) {
    k=Indx2Units[--i];
    insert(&BList[i],p,k);
    p += U2B(k);
    UDiff -= k;
  }
  insert( &BList[Units2Indx[UDiff-1]], p, UDiff );
}

void* AllocUnitsRare( uint indx ) {
  uint i = indx;
  do {
    if( ++i == N_INDEXES ) {
      if( !GlueCount-- ) {
        GlueFreeBlocks();
        if( BList[i=indx].avail() ) return remove(&BList[i]);
      } else {
        i = U2B(Indx2Units[indx]);
        return (UnitsStart-pText>i) ? UnitsStart-=i : NULL;
      }
    }
  } while( !BList[i].avail() );

  void* RetVal=remove(&BList[i]);
  SplitBlock( RetVal, i, indx );

  return RetVal;
}

void* AllocUnits( uint NU ) {
  uint indx = Units2Indx[NU-1];
  if( BList[indx].avail() ) return remove(&BList[indx]);
  void* RetVal=LoUnit;
  LoUnit += U2B(Indx2Units[indx]);
  if( LoUnit<=HiUnit ) return RetVal;
  LoUnit -= U2B(Indx2Units[indx]);
  return AllocUnitsRare(indx);
}

void* AllocContext() {
  if( HiUnit!=LoUnit ) return HiUnit-=UNIT_SIZE;
  return BList->avail() ? remove(BList) : AllocUnitsRare(0);
}

void FreeUnits( void* ptr, uint NU ) {
  uint indx = Units2Indx[NU-1];
  insert( &BList[indx], ptr, Indx2Units[indx] );
}

void FreeUnit( void* ptr ) {
  int i = (byte*)ptr > UnitsStart+128*1024 ? 0 : N_INDEXES;
  insert( &BList[i], ptr, 1 );
}

void UnitsCpy( void* Dest, void* Src, uint NU ) {
  memcpy( Dest, Src, 12*NU );
}

void* ExpandUnits( void* OldPtr, uint OldNU ) {
  uint i0 = Units2Indx[OldNU-1];
  uint i1 = Units2Indx[OldNU-1+1];
  if( i0==i1 ) return OldPtr;
  void* ptr = AllocUnits(OldNU+1);
  if( ptr ) {
    UnitsCpy( ptr, OldPtr, OldNU );
    insert( &BList[i0], OldPtr, OldNU );
  }
  return ptr;
}

void* ShrinkUnits( void* OldPtr, uint OldNU, uint NewNU ) {
  uint i0 = Units2Indx[OldNU-1];
  uint i1 = Units2Indx[NewNU-1];
  if( i0==i1 ) return OldPtr;
  if( BList[i1].avail() ) {
    void* ptr = remove(&BList[i1]);
    UnitsCpy( ptr, OldPtr, NewNU );
    insert( &BList[i0], OldPtr, Indx2Units[i0] );
    return ptr;
  } else {
    SplitBlock(OldPtr,i0,i1);
    return OldPtr;
  }
}

void* MoveUnitsUp( void* OldPtr, uint NU ) {
  uint indx = Units2Indx[NU-1];
  PrefetchData(OldPtr);
  if( (byte*)OldPtr > UnitsStart+128*1024 ||
      (BLK_NODE*)OldPtr > getNext(&BList[indx]) ) return OldPtr;

  void* ptr = remove(&BList[indx]);
  UnitsCpy( ptr, OldPtr, NU );

  insert( &BList[N_INDEXES], OldPtr, Indx2Units[indx] );

  return ptr;
}

void PrepareTextArea() {
  AuxUnit = (byte*)AllocContext();
  if( !AuxUnit ) {
    AuxUnit = UnitsStart;
  } else {
    if( AuxUnit==UnitsStart) AuxUnit = (UnitsStart+=UNIT_SIZE);
  }
}

void ExpandTextArea() {
  BLK_NODE* p;
  uint Count[N_INDEXES], i=0;
  memset( Count, 0, sizeof(Count) );

  if( AuxUnit!=UnitsStart ) {
    if( *(uint*)AuxUnit != ~uint(0) )
      UnitsStart += UNIT_SIZE;
    else
      insert( BList, AuxUnit, 1 );
  }

  while( (p=(BLK_NODE*)UnitsStart)->Stamp == ~uint(0) ) {
    MEM_BLK* pm = (MEM_BLK*)p;
    UnitsStart = (byte*)(pm + pm->NU);
    Count[Units2Indx[pm->NU-1]]++;
    i++;
    pm->Stamp = 0;
  }

  if( i ) {

    for( p=BList+N_INDEXES; p->NextIndx; p=getNext(p) ) {
      while( p->NextIndx && !getNext(p)->Stamp ) {
        Count[Units2Indx[((MEM_BLK*)getNext(p))->NU-1]]--;
        unlink(p);
        BList[N_INDEXES].Stamp--;
      }
      if( !p->NextIndx ) break;
    }

    for( i=0; i<N_INDEXES; i++ ) {
      for( p=BList+i; Count[i]!=0; p=getNext(p) ) {
        while( !getNext(p)->Stamp ) {
          unlink(p); BList[i].Stamp--;
          if ( !--Count[i] ) break;
        }
      }
    }

  }

}

static const int MAX_O=ORealMAX;

template <class T>
  T CLAMP( const T& X, const T& LoX, const T& HiX ) { return (X >= LoX)?((X <= HiX)?(X):(HiX)):(LoX); }

template <class T>
  void SWAP( T& t1, T& t2 ) { T tmp=t1; t1=t2; t2=tmp; }

void PrefetchData(void* Addr) {
  *(volatile byte*)Addr;
}

